cat > steps/Profile.tsx <<'EOF'
"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RadioGroup, RadioGroupItem } from "@atlas/ui-web/primitives/RadioGroup/RadioGroup"
import { ROLES, type OnboardingStepProps } from "../schema"
import { actionsStyle, errorStyle, fieldStyle, helpStyle, stepStyle, titleStyle } from "../styles"

type Errors = { fullName?: string; role?: string }

function validate(fullName: string, role: string): Errors {
  const errors: Errors = {}
  const name = fullName.trim()
  if (!name) errors.fullName = "Enter your full name."
  else if (name.length < 2) errors.fullName = "Full name must be at least 2 characters."
  if (!role) errors.role = "Choose the role that fits you best."
  return errors
}

export function Profile({ data, patch, next }: OnboardingStepProps) {
  const [errors, setErrors] = useState<Errors>({})
  const [submitted, setSubmitted] = useState(false)

  const revalidate = (fullName: string, role: string) => {
    if (submitted) setErrors(validate(fullName, role))
  }

  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    const found = validate(data.fullName, data.role)
    setSubmitted(true)
    setErrors(found)
    if (found.fullName) document.getElementById("onboarding-name")?.focus()
    else if (found.role) document.getElementById("onboarding-role-designer")?.focus()
    if (found.fullName || found.role) return
    patch({ fullName: data.fullName.trim() })
    next()
  }

  return (
    <form onSubmit={submit} noValidate style={stepStyle}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h2 style={titleStyle}>Tell us about you</h2>
        <p style={helpStyle}>This helps us tailor your workspace.</p>
      </div>

      <div style={fieldStyle}>
        <Label htmlFor="onboarding-name" required invalid={!!errors.fullName}>Full name</Label>
        <Input
          id="onboarding-name"
          autoComplete="name"
          value={data.fullName}
          invalid={!!errors.fullName}
          aria-describedby={errors.fullName ? "onboarding-name-error" : undefined}
          onChange={(e) => {
            patch({ fullName: e.target.value })
            revalidate(e.target.value, data.role)
          }}
          onBlur={() => submitted && setErrors(validate(data.fullName, data.role))}
        />
        {errors.fullName && <p id="onboarding-name-error" role="alert" style={errorStyle}>{errors.fullName}</p>}
      </div>

      <div style={fieldStyle}>
        <Label htmlFor="onboarding-role-designer" required invalid={!!errors.role}>Role</Label>
        <RadioGroup
          aria-label="Role"
          aria-describedby={errors.role ? "onboarding-role-error" : undefined}
          value={data.role}
          invalid={!!errors.role}
          required
          onValueChange={(role) => {
            patch({ role })
            revalidate(data.fullName, role)
          }}
        >
          {ROLES.map((r) => (
            <RadioGroupItem key={r.value} id={`onboarding-role-${r.value}`} value={r.value} label={r.label} invalid={!!errors.role} />
          ))}
        </RadioGroup>
        {errors.role && <p id="onboarding-role-error" role="alert" style={errorStyle}>{errors.role}</p>}
      </div>

      <div style={actionsStyle}>
        <Button type="submit" variant="primary" size="lg">Continue</Button>
      </div>
    </form>
  )
}
EOF
cat > steps/Preferences.tsx <<'EOF'
"use client"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RadioGroup, RadioGroupItem } from "@atlas/ui-web/primitives/RadioGroup/RadioGroup"
import { Switch } from "@atlas/ui-web/primitives/Switch/Switch"
import { PLANS, type OnboardingStepProps, type Plan } from "../schema"
import { actionsStyle, fieldStyle, helpStyle, stepStyle, titleStyle } from "../styles"

export function Preferences({ data, patch, next, back }: OnboardingStepProps) {
  const skip = () => {
    patch({ emailNotifications: false, pushNotifications: false, plan: "free", skippedPreferences: true })
    next()
  }
  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    patch({ skippedPreferences: false })
    next()
  }

  return (
    <form onSubmit={submit} noValidate style={stepStyle}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h2 style={titleStyle}>Your preferences</h2>
        <p style={helpStyle}>You can change these any time. Skip to use the defaults.</p>
      </div>

      <div style={fieldStyle}>
        <Switch
          id="onboarding-email"
          label="Email notifications"
          description="Product news and account updates"
          checked={data.emailNotifications}
          onCheckedChange={(emailNotifications) => patch({ emailNotifications })}
        />
        <Switch
          id="onboarding-push"
          label="Push notifications"
          description="Alerts on this device"
          checked={data.pushNotifications}
          onCheckedChange={(pushNotifications) => patch({ pushNotifications })}
        />
      </div>

      <div style={fieldStyle}>
        <Label htmlFor="onboarding-plan-free">Plan</Label>
        <RadioGroup
          aria-label="Plan"
          variant="card"
          value={data.plan}
          onValueChange={(plan) => patch({ plan: plan as Plan })}
        >
          {PLANS.map((p) => (
            <RadioGroupItem
              key={p.value}
              id={`onboarding-plan-${p.value}`}
              variant="card"
              value={p.value}
              label={p.label}
              description={p.description}
            />
          ))}
        </RadioGroup>
      </div>

      <div style={actionsStyle}>
        <Button type="submit" variant="primary" size="lg">Continue</Button>
        <div style={{ display: "flex", gap: "var(--atlas-spacing-2)" }}>
          <Button type="button" variant="ghost" size="md" onClick={back}>Back</Button>
          <Button type="button" variant="ghost" size="md" onClick={skip}>Skip</Button>
        </div>
      </div>
    </form>
  )
}
EOF
cat > steps/Done.tsx <<'EOF'
"use client"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { PLANS, type OnboardingStepProps } from "../schema"
import { actionsStyle, helpStyle, stepStyle, titleStyle } from "../styles"

export function Done({ data, back, goTo }: OnboardingStepProps) {
  const plan = PLANS.find((p) => p.value === data.plan)?.label
  const firstName = data.fullName.split(" ")[0]
  return (
    <div style={stepStyle}>
      <div style={{ display: "flex", flexDirection: "column", gap: "var(--atlas-spacing-1)" }}>
        <h2 style={titleStyle}>You&apos;re all set, {firstName}</h2>
        <p style={helpStyle}>
          {data.skippedPreferences
            ? "We used the default preferences. You can change them in settings."
            : `You're on the ${plan} plan. You can change your preferences in settings.`}
        </p>
      </div>
      <div style={actionsStyle}>
        <Button variant="primary" size="lg" onClick={() => goTo(0)}>Continue to app</Button>
        <div>
          <Button variant="ghost" size="md" onClick={back}>Back</Button>
        </div>
      </div>
    </div>
  )
}
EOF
