"use client"
import { useState } from "react"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Input } from "@atlas/ui-web/primitives/Input/Input"
import { Label } from "@atlas/ui-web/primitives/Label/Label"
import { RadioGroup, RadioGroupItem } from "@atlas/ui-web/primitives/RadioGroup/RadioGroup"
import { ROLES, type OnboardingStepProps } from "../schema"
import { actionsStyle, errorStyle, fieldStyle, headingGroupStyle, helpStyle, stepStyle, titleStyle } from "../styles"

type Errors = { fullName?: string; role?: string }

function validate(fullName: string, role: string): Errors {
  const errors: Errors = {}
  const name = fullName.trim()
  if (!name) errors.fullName = "Enter your full name."
  else if (name.length < 2) errors.fullName = "Full name must be at least 2 characters."
  if (!role) errors.role = "Choose the role that fits you best."
  return errors
}

export function Profile({ data, patch, next }: OnboardingStepProps) {
  const [errors, setErrors] = useState<Errors>({})
  const [submitted, setSubmitted] = useState(false)

  const revalidate = (fullName: string, role: string) => {
    if (submitted) setErrors(validate(fullName, role))
  }

  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    const found = validate(data.fullName, data.role)
    setSubmitted(true)
    setErrors(found)
    if (found.fullName) document.getElementById("onboarding-name")?.focus()
    else if (found.role) document.getElementById("onboarding-role-designer")?.focus()
    if (found.fullName || found.role) return
    patch({ fullName: data.fullName.trim() })
    next()
  }

  return (
    <form onSubmit={submit} noValidate style={stepStyle}>
      <div style={headingGroupStyle}>
        <h2 style={titleStyle}>Tell us about you</h2>
        <p style={helpStyle}>This helps us tailor your workspace.</p>
      </div>

      <div style={fieldStyle}>
        <Label htmlFor="onboarding-name" required invalid={!!errors.fullName}>Full name</Label>
        <Input
          id="onboarding-name"
          autoComplete="name"
          value={data.fullName}
          invalid={!!errors.fullName}
          aria-describedby={errors.fullName ? "onboarding-name-error" : undefined}
          onChange={(e) => {
            patch({ fullName: e.target.value })
            revalidate(e.target.value, data.role)
          }}
          onBlur={() => revalidate(data.fullName, data.role)}
        />
        {errors.fullName && <p id="onboarding-name-error" role="alert" style={errorStyle}>{errors.fullName}</p>}
      </div>

      <div style={fieldStyle}>
        <Label htmlFor="onboarding-role-designer" required invalid={!!errors.role}>Role</Label>
        <RadioGroup
          aria-label="Role"
          aria-describedby={errors.role ? "onboarding-role-error" : undefined}
          value={data.role}
          invalid={!!errors.role}
          required
          onValueChange={(role) => {
            patch({ role })
            revalidate(data.fullName, role)
          }}
        >
          {ROLES.map((r) => (
            <RadioGroupItem key={r.value} id={`onboarding-role-${r.value}`} value={r.value} label={r.label} invalid={!!errors.role} />
          ))}
        </RadioGroup>
        {errors.role && <p id="onboarding-role-error" role="alert" style={errorStyle}>{errors.role}</p>}
      </div>

      <div style={actionsStyle}>
        <Button type="submit" variant="primary" size="lg">Continue</Button>
      </div>
    </form>
  )
}

