import { PLANS, type OnboardingStepProps, type Plan } from "../schema"
import { actionsStyle, fieldStyle, headingGroupStyle, helpStyle, stepStyle, titleStyle } from "../styles"

export function Preferences({ data, patch, next, back }: OnboardingStepProps) {
  const skip = () => {
    patch({ emailNotifications: false, pushNotifications: false, plan: "free", skippedPreferences: true })
    next()
  }
  const submit = (e: React.FormEvent) => {
    e.preventDefault()
    patch({ skippedPreferences: false })
    next()
  }

  return (
    <form onSubmit={submit} noValidate style={stepStyle}>
      <div style={headingGroupStyle}>
        <h2 style={titleStyle}>Your preferences</h2>
        <p style={helpStyle}>You can change these any time. Skip to use the defaults.</p>
      </div>

      <div style={fieldStyle}>
        <Switch
          id="onboarding-email"
          label="Email notifications"
          description="Product news and account updates"
          checked={data.emailNotifications}
          onCheckedChange={(emailNotifications) => patch({ emailNotifications })}
        />
        <Switch
          id="onboarding-push"
          label="Push notifications"
          description="Alerts on this device"
          checked={data.pushNotifications}
          onCheckedChange={(pushNotifications) => patch({ pushNotifications })}
        />
      </div>

      <div style={fieldStyle}>
        <Label htmlFor="onboarding-plan-free">Plan</Label>
        <RadioGroup
          aria-label="Plan"
          variant="card"
          value={data.plan}
          onValueChange={(plan) => patch({ plan: plan as Plan })}
        >
          {PLANS.map((p) => (
            <RadioGroupItem
              key={p.value}
              id={`onboarding-plan-${p.value}`}
              variant="card"
              value={p.value}
              label={p.label}
              description={p.description}
            />
          ))}
        </RadioGroup>
      </div>

      <div style={actionsStyle}>
        <Button type="submit" variant="primary" size="lg">Continue</Button>
        <div style={{ display: "flex", gap: "var(--atlas-spacing-2)" }}>
          <Button type="button" variant="ghost" size="md" onClick={back}>Back</Button>
          <Button type="button" variant="ghost" size="md" onClick={skip}>Skip</Button>
        </div>
      </div>
    </form>
  )
}

